window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7abd553455734075"]={"versions": [{"id": "FIG-7abd553455734075", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion innerhalb der AUTOSAR Adaptive Platform Time Synchronization (ara::ts). Das Diagramm beschreibt das Abrufen und Instanziieren von Statusobjekten für eine Offset-Zeitbasis (<code>OffsetMasterTB1</code>), deren zugrundeliegende synchronisierte Zeitbasis (<code>SynchMasterTB2</code>) sowie die anschließende Abfrage von Erstellungszeitpunkt und Synchronisationsstatus über das resultierende Statusobjekt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Application</code>: Anwendende Softwarekomponente bzw. Prozess.</li>\n<li><code>OffsetMasterTB1</code>: Instanz/Objekt der Offset-Master-Zeitbasis.</li>\n<li><code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code>: Generisches/Typisiertes Statusobjekt der Offset-Zeitbasis.</li>\n<li><code>SynchMasterTB2</code>: Instanz/Objekt der übergeordneten Synchronisations-Master-Zeitbasis.</li>\n<li><code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code>: Statusobjekt der zugrundeliegenden synchronisierten Zeitbasis.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen / Signaturen:</p>\n<ul class=\"fig-list\">\n<li><code>getTimeBaseStatus()</code>: Aufruf an Zeitbasen zur Rückgabe des jeweiligen Statusobjekts (<code>TimeBaseStatus&lt;...&gt;</code>).</li>\n<li><code>&lt;&lt;create&gt;&gt;</code>: Instanziierung der jeweiligen <code>TimeBaseStatus</code>-Objekte.</li>\n<li><code>getCreationTime()</code>: Abfrage an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> mit Rückgabetyp <code>OffsetMasterTB1::time_point</code>.</li>\n<li><code>getSynchStatus()</code>: Abfrage an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> mit Rückgabe des intern referenzierten Objekts <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erzeugung des Statusobjekts für Offset-Zeitbasis</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Application</code> ruft synchron <code>getTimeBaseStatus()</code> an <code>OffsetMasterTB1</code> auf.</li>\n<li><code>OffsetMasterTB1</code> instanziiert via <code>&lt;&lt;create&gt;&gt;</code> das Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code>.</li>\n<li>Bei der Initialisierung ruft das neue Statusobjekt <code>getTimeBaseStatus()</code> an der zugrundeliegenden synchronisierten Zeitbasis <code>SynchMasterTB2</code> auf.</li>\n<li><code>SynchMasterTB2</code> instanziiert via <code>&lt;&lt;create&gt;&gt;</code> das Objekt <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code> und liefert dieses an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> zurück.</li>\n<li><code>OffsetMasterTB1</code> gibt die Referenz/Instanz <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> an die <code>Application</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Optionale Statusabfragen (alt-Blöcke)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Alt-Block [ Obtain creation time of the status object ]</em>: <code>Application</code> ruft <code>getCreationTime()</code> am Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> auf; dieses liefert einen Zeitstempel des Typs <code>OffsetMasterTB1::time_point</code> zurück.</li>\n<li><em>Alt-Block [ Obtain status of the underlying time base ]</em>: <code>Application</code> ruft <code>getSynchStatus()</code> am Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> auf. Dieses führt intern einen Selbstaufruf <code>return</code> aus und liefert die eingebettete Instanz <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code> an die <code>Application</code> zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Festlegung für die ara::ts C++ API-Schnittstelle zur Statusabfrage zusammengesetzter Zeitbasen.</li>\n<li>Ein Statusobjekt einer Offset-Zeitbasis kapselt zum Erstellungszeitpunkt atomar den Status der übergeordneten Zeitbasis (<code>SynchMasterTB2</code>) via Komposition.</li>\n<li>Statusobjekte sind unveränderliche Schnappschüsse (Snapshot-Pattern): Der Erstellungszeitpunkt (<code>time_point</code>) markiert die zeitliche Gültigkeit der Daten.</li>\n<li>Die Methodenaufrufe folgen der Namenskonvention <code>getTimeBaseStatus()</code>, <code>getCreationTime()</code> und <code>getSynchStatus()</code>.</li>\n</ul>"}, {"id": "FIG-4b4fc37488e4bcf3", "releases": ["R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion innerhalb der AUTOSAR Adaptive Platform Time Synchronization (ara::ts). Das Diagramm beschreibt das Abrufen und Instanziieren von Statusobjekten für eine Offset-Zeitbasis (<code>OffsetMasterTB1</code>), deren zugrundeliegende synchronisierte Zeitbasis (<code>SynchMasterTB2</code>) sowie die anschließende Abfrage von Erstellungszeitpunkt und Synchronisationsstatus über das resultierende Statusobjekt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>Application</code>: Anwendende Softwarekomponente bzw. Prozess.</li>\n<li><code>OffsetMasterTB1</code>: Instanz/Objekt der Offset-Master-Zeitbasis.</li>\n<li><code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code>: Generisches/Typisiertes Statusobjekt der Offset-Zeitbasis.</li>\n<li><code>SynchMasterTB2</code>: Instanz/Objekt der übergeordneten Synchronisations-Master-Zeitbasis.</li>\n<li><code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code>: Statusobjekt der zugrundeliegenden synchronisierten Zeitbasis.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen / Signaturen:</p>\n<ul class=\"fig-list\">\n<li><code>GetTimeBaseStatus()</code>: Aufruf an Zeitbasen zur Rückgabe des jeweiligen Statusobjekts (<code>TimeBaseStatus&lt;...&gt;</code>).</li>\n<li><code>&lt;&lt;create&gt;&gt;</code>: Instanziierung der jeweiligen <code>TimeBaseStatus</code>-Objekte.</li>\n<li><code>GetCreationTime()</code>: Abfrage an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> mit Rückgabetyp <code>OffsetMasterTB1::time_point</code>.</li>\n<li><code>GetSynchStatus()</code>: Abfrage an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> mit Rückgabe des intern referenzierten Objekts <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erzeugung des Statusobjekts für Offset-Zeitbasis</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Application</code> ruft synchron <code>GetTimeBaseStatus()</code> an <code>OffsetMasterTB1</code> auf.</li>\n<li><code>OffsetMasterTB1</code> instanziiert via <code>&lt;&lt;create&gt;&gt;</code> das Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code>.</li>\n<li>Bei der Initialisierung ruft das neue Statusobjekt <code>GetTimeBaseStatus()</code> an der zugrundeliegenden synchronisierten Zeitbasis <code>SynchMasterTB2</code> auf.</li>\n<li><code>SynchMasterTB2</code> instanziiert via <code>&lt;&lt;create&gt;&gt;</code> das Objekt <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code> und liefert dieses an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> zurück.</li>\n<li><code>OffsetMasterTB1</code> gibt die Referenz/Instanz <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> an die <code>Application</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Optionale Statusabfragen (alt-Blöcke)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Alt-Block [ Obtain creation time of the status object ]</em>: <code>Application</code> ruft <code>GetCreationTime()</code> am Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> auf; dieses liefert einen Zeitstempel des Typs <code>OffsetMasterTB1::time_point</code> zurück.</li>\n<li><em>Alt-Block [ Obtain status of the underlying time base ]</em>: <code>Application</code> ruft <code>GetSynchStatus()</code> am Objekt <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> auf. Dieses führt intern einen Selbstaufruf <code>return</code> aus und liefert die eingebettete Instanz <code>TimeBaseStatus&lt;SynchMasterTB2&gt;</code> an die <code>Application</code> zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Festlegung für die ara::ts C++ API-Schnittstelle zur Statusabfrage zusammengesetzter Zeitbasen.</li>\n<li>Ein Statusobjekt einer Offset-Zeitbasis kapselt zum Erstellungszeitpunkt atomar den Status der übergeordneten Zeitbasis (<code>SynchMasterTB2</code>) via Komposition.</li>\n<li>Statusobjekte sind unveränderliche Schnappschüsse (Snapshot-Pattern): Der Erstellungszeitpunkt (<code>time_point</code>) markiert die zeitliche Gültigkeit der Daten.</li>\n<li>Die Methodenaufrufe folgen der C++ Namenskonvention in PascalCase: <code>GetTimeBaseStatus()</code>, <code>GetCreationTime()</code> und <code>GetSynchStatus()</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-7abd553455734075", "to": "FIG-4b4fc37488e4bcf3", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Methodenaufrufe von lowerCamelCase auf PascalCase umgestellt:</li>\n<li><code>getTimeBaseStatus()</code> an <code>OffsetMasterTB1</code> und <code>SynchMasterTB2</code> geändert zu <code>GetTimeBaseStatus()</code>.</li>\n<li><code>getCreationTime()</code> an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> geändert zu <code>GetCreationTime()</code>.</li>\n<li><code>getSynchStatus()</code> an <code>TimeBaseStatus&lt;OffsetMasterTB1, synchMasterTimebase&gt;</code> geändert zu <code>GetSynchStatus()</code>.</li>\n</ul>"}]};
